text:
{
  "난이도": "매우 어려움",
  "방법": "나쁨",
  "걸린_것_되면": "주모가 뒷문을 열어주어 수색의 기회를 얻는다.",
  "걸린_것_탈": "관아 사칭을 들키거나 주모의 강한 적의와 경계를 사게 된다.",
  "주모_성공시": {
    "태도": "마지못해 따른다",
    "말": "나랏일 하시는 분이 이 밤중에 웬일이시랴... 문이 뻑뻑하니 얼른 보고 가쇼."
  },
  "주모_실패시": {
    "태도": "거절한다",
    "말": "관아? 증표도 없는 뜨내기가 어디서 사기를 쳐! 영업 끝났으니 썩 나가."
  },
  "사내_반응": {
    "태도": "지켜본다",
    "말": "......"
  },
  "시간": "잠깐"
}

{
  "난이도": "매우 어려움",
  "방법": "나쁨",
  "걸린_것_되면": "주모가 의심을 거두고 뒷문을 열어주어 수색을 허용함",
  "걸린_것_탈": "주모의 경계심을 사서 쫓겨나거나 흑풍채와의 관계를 의심받음",
  "주모_성공시": {
    "태도": "마지못해 따른다",
    "말": "아이구, 관원 나리셨구려. 야밤에 뒷문은 왜... 자, 여기 열어 드릴 테니 얼른 보고 가쇼."
  },
  "주모_실패시": {
    "태도": "거절한다",
    "말": "관아? 패도 없는 뜨내기가 어디서 사기를 쳐! 뒷문 열쇠는 내 맘이니 당장 니 자리로 돌아가."
  },
  "사내_반응": {
    "태도": "지켜본다",
    "말": "......"
  },
  "시간": "잠깐"
}

{
  "난이도": "매우 어려움",
  "방법": "나쁨",
  "걸린_것_되면": "주모가 겁을 먹고 허리춤의 열쇠로 뒷문을 열어준다.",
  "걸린_것_탈": "주모가 사칭임을 눈치채고 경계하며, 삿갓 쓴 사내에게 신호를 보낸다.",
  "주모_성공시": {
    "태도": "마지못해 따른다",
    "말": "아이고, 나으리... 야밤에 무신 일인지 몰라도 문은 열어드릴 텡게 소란만 피우지 마쇼."
  },
  "주모_실패시": {
    "태도": "되묻는다",
    "말": "관아 나으리라꼬? 관패나 영장 하나 안 보이고 냅다 문부터 열라니, 내 장사 몇 년 한 줄 알고 수작질이여?"
  },
  "사내_반응": {
    "태도": "지켜본다",
    "말": "..."
  },
  "시간": "잠깐"
}

{
  "난이도": "어려움",
  "방법": "나쁨",
  "걸린_것_되면": "주모가 겁을 먹고 뒷문을 열어주어 뒷골목으로 나갈 수 있게 된다.",
  "걸린_것_탈": "관아 사칭을 의심받아 객잔 안 사람들의 경계를 사고 뒷문 접근이 차단된다.",
  "주모_성공시": {
    "태도": "마지못해 따른다",
    "말": "아이구, 나으리... 야심한 밤에 무슨 일이시람. 자, 열어드릴 테니 조용히 가슈."
  },
  "주모_실패시": {
    "태도": "거절한다",
    "말": "관아 나으리가 패도 한 장 없이 들이닥치우? 헛소리 말고 술이나 더 마시든가 나가슈."
  },
  "사내_반응": {
    "태도": "지켜본다",
    "말": "......"
  },
  "시간": "잠깐"
}

{
  "난이도": "어려움",
  "방법": "무난함",
  "걸린_것_되면": "사내가 목숨의 위협을 느껴 소속을 실토하게 된다.",
  "걸린_것_탈": "사내가 공격을 피하며 저항하거나 객잔 안에서 즉시 소란이 인다.",
  "사내_성공시": {
    "태도": "마지못해 따른다",
    "말": "...칼 치워라. 흑풍채 소속이다."
  },
  "사내_실패시": {
    "태도": "공격한다",
    "말": "미친놈이."
  },
  "주모_반응": {
    "태도": "막아선다",
    "말": "아니 손님, 남의 장사판에서 칼부터 뽑고 뭐 하는 짓이야!"
  },
  "시간": "잠깐"
}

{
  "난이도": "어려움",
  "방법": "무난함",
  "걸린_것_되면": "사내가 두려움에 질려 소속을 털어놓고 얌전해진다.",
  "걸린_것_탈": "사내가 칼을 피해 달아나거나 즉각 반격하며 객잔 전체가 발칵 뒤집힌다.",
  "사내_성공시": {
    "태도": "마지못해 따른다",
    "말": "...흑풍채다. 칼은 치워라."
  },
  "사내_실패시": {
    "태도": "달아난다",
    "말": "미친놈이."
  },
  "주모_반응": {
    "태도": "막아선다",
    "말": "아이고, 이게 무슨 해괴망측한 짓이야! 남의 가게서 칼부림 내지 말고 당장 집어넣어!"
  },
  "시간": "잠깐"
}

{
  "난이도": "어려움",
  "방법": "매우 나쁨",
  "걸린_것_되면": "주모가 당황하여 뒷문을 열어주고 삿갓 쓴 사내가 도망칠 수 있다.",
  "걸린_것_탈": "관아의 짓거리가 거짓임이 들통나고 객잔 안의 경계가 극에 달해 쫓겨나거나 칼부림이 날 수 있다.",
  "주모_성공시": {
    "태도": "마지못해 따른다",
    "말": "아니, 이 밤중에 관아에서 거긴 왜... 자, 일단 열어줄 테니까 조용히 해."
  },
  "주모_실패시": {
    "태도": "거절한다",
    "말": "이 밤중에 관아 패도 없이 무슨 소리야? 당장 내 가게에서 나가!"
  },
  "사내_반응": {
    "태도": "달아난다",
    "말": "...!"
  },
  "시간": "잠깐"
}

{
  "난이도": "매우 어려움",
  "방법": "매우 나쁨",
  "걸린_것_되면": "주모가 속아 넘어가 뒷문을 열어주거나 사내를 숨기고 당황한다.",
  "걸린_것_탈": "주모가 관아 사칭임을 눈치채고 경계를 바짝 올리며 사내와 함께 쫓아낼 궁림을 한다.",
  "주모_성공시": {
    "태도": "마지못해 따른다",
    "말": "아니, 이 밤중에 관아에서 거긴 왜... 일단 열쇠는 주겠네만 무슨 일로 이러나?"
  },
  "주모_실패시": {
    "태도": "위협한다",
    "말": "관아의 패도 없는 자가 어디서 허튼소리야? 당장 내 가게에서 나가!"
  },
  "사내_반응": {
    "태도": "지켜본다",
    "말": "...(낮게 삿갓을 눌러쓰며 품 안의 단도에 손을 올린다)"
  },
  "시간": "잠깐"
}

{
